<style>
.mp-practicum-list-frame{display:flex;flex-direction:column;flex:1 1 0%;min-width:0;min-height:0;height:auto}
.mp-practicum-list-frame>.mp-page-header{position:relative;flex-shrink:0;padding:0 var(--mp-list-divider-inset,24px) 20px;margin:0 calc(-1 * var(--mp-list-divider-inset,24px)) 24px;border-bottom:1px solid #DFE1E7}
.mp-practicum-list-frame>.mp-page-header::after{display:none}
.mp-practicum-list-frame>.mp-card{display:flex;flex-direction:column;flex:1 1 0%;min-height:0;min-width:0;margin-top:0}
.mp-practicum-list-frame>.mp-card>:not(.mp-card-body):not(.mp-data-scroll){flex-shrink:0}
.mp-practicum-list-frame>.mp-card>.mp-card-body,.mp-practicum-list-frame>.mp-card>.mp-data-scroll{flex:1 1 0%;min-height:0;overflow:auto}
@media(min-width:768px){.mp-app .mp-box-body:has(>.mp-practicum-list-frame){display:flex;flex-direction:column;overflow:hidden;scrollbar-gutter:auto}}
@media(max-width:767px){.mp-practicum-list-frame{height:auto}.mp-practicum-list-frame>.mp-card{flex:auto}.mp-practicum-list-frame>.mp-card>.mp-card-body,.mp-practicum-list-frame>.mp-card>.mp-data-scroll{flex:auto}}
</style>
